    34	fn mapping(view: SceneView<'_>) -> Option<(f64, f64, f64, f64)> {
    35	    let v = view.viewport;
    36	    if v.width == 0
    37	        || v.height == 0
    38	        || ![v.view_x, v.view_y, v.view_width, v.view_height]
    39	            .into_iter()
    40	            .all(f64::is_finite)
    41	        || v.view_width <= 0.
    42	        || v.view_height <= 0.
    43	    {
    44	        return None;
    45	    }
    46	    let (mut sx, mut sy) = (
    47	        f64::from(v.width) / v.view_width,
    48	        f64::from(v.height) / v.view_height,
    49	    );
    50	    let (mut ox, mut oy) = (0., 0.);
    51	    let mut a = v.aspect;
    52	    if !a.set {
    53	        a.align_x = 0.5;
    54	        a.align_y = 0.5;
    55	    }
    56	    if !a.none {
    57	        let s = if a.slice { sx.max(sy) } else { sx.min(sy) };
    58	        sx = s;
    59	        sy = s;
    60	        ox = (f64::from(v.width) - v.view_width * s) * a.align_x;
    61	        oy = (f64::from(v.height) - v.view_height * s) * a.align_y;
    62	    }
    63	    [sx, sy, ox, oy]
    64	        .into_iter()
    65	        .all(f64::is_finite)
    66	        .then_some((sx, sy, ox, oy))
    67	}
