    69	fn bounds_controlled(
    70	    view: SceneView<'_>,
    71	    id: ShapeId,
    72	    control: &mut dyn WorkControl,
    73	) -> Result<Option<Selection>> {
    74	    let Some(shape) = view.shape(id) else {
    75	        return Ok(None);
    76	    };
    77	    let Some(edges) = shape.edges.slice(view.edges) else {
    78	        return Ok(None);
    79	    };
    80	    let (min_x, min_y, max_x, max_y) = if let Some(first) = edges.first() {
    81	        let mut b = (first.a.x, first.a.y, first.a.x, first.a.y);
    82	        for edge in edges {
    83	            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
    84	            for p in [edge.a, edge.b] {
    85	                if !p.x.is_finite() || !p.y.is_finite() {
    86	                    return Ok(None);
    87	                }
    88	                b.0 = b.0.min(p.x);
    89	                b.1 = b.1.min(p.y);
    90	                b.2 = b.2.max(p.x);
    91	                b.3 = b.3.max(p.y);
    92	            }
    93	        }
    94	        b
    95	    } else {
    96	        (0., 0., 0., 0.)
    97	    };
    98	    let Some((sx, sy, ox, oy)) = mapping(view) else {
    99	        return Ok(None);
   100	    };
   101	    let left = ox + (min_x - view.viewport.view_x) * sx;
   102	    let top = oy + (min_y - view.viewport.view_y) * sy;
   103	    let right = ox + (max_x - view.viewport.view_x) * sx;
   104	    let bottom = oy + (max_y - view.viewport.view_y) * sy;
   105	    if ![left, top, right, bottom].into_iter().all(f64::is_finite) {
   106	        return Ok(None);
   107	    }
   108	    Ok(Some(Selection {
   109	        shape: id,
   110	        source: shape.source.element,
   111	        user_bounds: Rect {
   112	            x: min_x,
   113	            y: min_y,
   114	            width: max_x - min_x,
   115	            height: max_y - min_y,
   116	        },
   117	        device_bounds: Rect {
   118	            x: left,
   119	            y: top,
   120	            width: right - left,
   121	            height: bottom - top,
   122	        },
   123	        transform: shape.source.transform,
   124	    }))
   125	}
