   142	fn segment_distance(p: Point, a: Point, b: Point) -> f64 {
   143	    let dx = b.x - a.x;
   144	    let dy = b.y - a.y;
   145	    let length2 = dx * dx + dy * dy;
   146	    if length2 == 0. {
   147	        return (p.x - a.x).hypot(p.y - a.y);
   148	    }
   149	    let t = (((p.x - a.x) * dx + (p.y - a.y) * dy) / length2).clamp(0., 1.);
   150	    (p.x - (a.x + t * dx)).hypot(p.y - (a.y + t * dy))
   151	}
