   153	fn fill_contains(
   154	    view: SceneView<'_>,
   155	    id: ShapeId,
   156	    x: f64,
   157	    y: f64,
   158	    control: &mut dyn WorkControl,
   159	) -> Result<bool> {
   160	    let Some(shape) = view.shape(id) else {
   161	        return Ok(false);
   162	    };
   163	    let Some(edges) = shape.edges.slice(view.edges) else {
   164	        return Ok(false);
   165	    };
   166	    let mut winding = 0i32;
   167	    let mut parity = false;
   168	    let mut visible = view
   169	        .fill_paint(id)
   170	        .is_some_and(|paint| paint.kind == PaintKind::Image);
   171	    for (i, edge) in edges.iter().enumerate() {
   172	        control.charge(WorkKind::FillEdgeTest, 1).map_err(stopped)?;
   173	        visible |= view
   174	            .edge_colors
   175	            .get(shape.edges.first + i)
   176	            .is_some_and(|c| c[3] != 0);
   177	        let up = edge.a.y <= y && edge.b.y > y;
   178	        let down = edge.b.y <= y && edge.a.y > y;
   179	        if !up && !down {
   180	            continue;
   181	        }
   182	        let crossing = edge.a.x + (y - edge.a.y) * (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
   183	        if crossing > x {
   184	            winding += if up { 1 } else { -1 };
   185	            parity = !parity;
   186	        }
   187	    }
   188	    Ok(visible && shape.filled && if shape.evenodd { parity } else { winding != 0 })
   189	}
