   191	fn stroke_contains(
   192	    view: SceneView<'_>,
   193	    id: ShapeId,
   194	    p: Point,
   195	    tolerance: f64,
   196	    control: &mut dyn WorkControl,
   197	) -> Result<bool> {
   198	    let Some(shape) = view.shape(id) else {
   199	        return Ok(false);
   200	    };
   201	    if shape.stroke.rgba[3] == 0 || shape.stroke.width <= 0. {
   202	        return Ok(false);
   203	    }
   204	    let inv = shape.stroke_inverse;
   205	    let Some(local) = vexel_geometry::affine_map_point(inv, p) else {
   206	        return Ok(false);
   207	    };
   208	    let norm = (inv.a * inv.a + inv.b * inv.b + inv.c * inv.c + inv.d * inv.d).sqrt();
   209	    let radius = shape.stroke.width * 0.5 + tolerance * norm;
   210	    let Some(subpaths) = shape.subpaths.slice(view.path_subpaths) else {
   211	        return Ok(false);
   212	    };
   213	    let Some(edges) = shape.edges.slice(view.edges) else {
   214	        return Ok(false);
   215	    };
   216	    if !subpaths.is_empty() {
   217	        for path in subpaths {
   218	            let Some(end) = path.first_edge.checked_add(path.edge_count) else {
   219	                return Ok(false);
   220	            };
   221	            let Some(path_edges) = view.edges.get(path.first_edge..end) else {
   222	                return Ok(false);
   223	            };
   224	            let count = path_edges.len().saturating_sub(usize::from(!path.closed));
   225	            for edge in &path_edges[..count] {
   226	                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
   227	                let (Some(a), Some(b)) = (
   228	                    vexel_geometry::affine_map_point(inv, edge.a),
   229	                    vexel_geometry::affine_map_point(inv, edge.b),
   230	                ) else {
   231	                    return Ok(false);
   232	                };
   233	                if segment_distance(local, a, b) <= radius {
   234	                    return Ok(true);
   235	                }
   236	            }
   237	        }
   238	        return Ok(false);
   239	    }
   240	    let count = edges
   241	        .len()
   242	        .saturating_sub(usize::from(!shape.stroke_closed));
   243	    for edge in &edges[..count] {
   244	        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
   245	        let (Some(a), Some(b)) = (
   246	            vexel_geometry::affine_map_point(inv, edge.a),
   247	            vexel_geometry::affine_map_point(inv, edge.b),
   248	        ) else {
   249	            return Ok(false);
   250	        };
   251	        if segment_distance(local, a, b) <= radius {
   252	            return Ok(true);
   253	        }
   254	    }
   255	    Ok(false)
   256	}
