   258	/// Reverse-painter selection using the caller's concrete clip provider and work controller.
   259	pub fn hit_test(
   260	    view: SceneView<'_>,
   261	    x: f64,
   262	    y: f64,
   263	    tolerance: f64,
   264	    resources: &dyn KernelResources,
   265	    control: &mut dyn WorkControl,
   266	) -> Result<Option<Selection>> {
   267	    if ![x, y, tolerance].into_iter().all(f64::is_finite)
   268	        || tolerance < 0.
   269	        || tolerance > 1_000_000.
   270	    {
   271	        return Err(invalid(0));
   272	    }
   273	    for i in (0..view.shapes.len()).rev() {
   274	        control.checkpoint().map_err(stopped)?;
   275	        let Some(id) = view.shape_id(i) else { continue };
   276	        let shape = view.shape(id).ok_or_else(|| invalid(0))?;
   277	        if let Some(clip) = shape.clip {
   278	            if !resources.clip_contains(view, clip, x, y, control)? {
   279	                continue;
   280	            }
   281	        }
   282	        if !fill_contains(view, id, x, y, control)?
   283	            && !stroke_contains(view, id, Point { x, y }, tolerance, control)?
   284	        {
   285	            continue;
   286	        }
   287	        return bounds_controlled(view, id, control);
   288	    }
   289	    Ok(None)
   290	}
