   298	/// Controlled source lookup; each source record is charged before inspection.
   299	pub fn element_at_offset_controlled(
   300	    view: SceneView<'_>,
   301	    offset: usize,
   302	    control: &mut dyn WorkControl,
   303	) -> Result<Option<Selection>> {
   304	    let mut best: Option<(usize, usize)> = None;
   305	    for (i, shape) in view.shapes.iter().enumerate() {
   306	        control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
   307	        let span = shape.source.element;
   308	        if span.start > offset || offset >= span.end || span.start >= span.end {
   309	            continue;
   310	        }
   311	        let length = span.end - span.start;
   312	        if best.is_none_or(|(best_i, best_len)| {
   313	            length < best_len || (length == best_len && i > best_i)
   314	        }) {
   315	            best = Some((i, length));
   316	        }
   317	    }
   318	    match best {
   319	        Some((i, _)) => match view.shape_id(i) {
   320	            Some(id) => bounds_controlled(view, id, control),
   321	            None => Ok(None),
   322	        },
   323	        None => Ok(None),
   324	    }
   325	}
