    30	/// Per-job admission scope. The shared ledger remains the only lease registry; this stores
    31	/// just an active-count bound and an unforgeable shared owner token.
    32	#[derive(Debug)]
    33	pub struct AllocationTracking {
    34	    owner: Arc<()>,
    35	    active: usize,
    36	}
    37	#[derive(Debug)]
    38	pub struct TrackedAllocationLease {
    39	    owner: Arc<()>,
    40	    lease: AllocationLease,
    41	}
    42	
    43	impl AllocationTracking {
    44	    pub fn tracking_start(job: &ChargeLedger) -> Self {
    45	        let _ = job;
    46	        Self {
    47	            owner: Arc::new(()),
    48	            active: 0,
    49	        }
    50	    }
    51	    pub fn track_capacity<T>(
    52	        &mut self,
    53	        job: &mut ChargeLedger,
    54	        tag: AllocationTag,
    55	        values: &Vec<T>,
    56	    ) -> Result<TrackedAllocationLease> {
    57	        if self.active >= SVG_ALLOC_TRACKER_CAPACITY {
    58	            return Err(Diagnostic {
    59	                kind: ErrorKind::Limit(LimitKind::Nodes),
    60	                offset: 0,
    61	            });
    62	        }
    63	        let active = self.active.checked_add(1).ok_or_else(arithmetic)?;
    64	        let lease = job.admit_vec(tag, values)?;
    65	        self.active = active;
    66	        Ok(TrackedAllocationLease {
    67	            owner: self.owner.clone(),
    68	            lease,
    69	        })
    70	    }
    71	    pub fn release(
    72	        &mut self,
    73	        job: &mut ChargeLedger,
    74	        lease: &TrackedAllocationLease,
    75	    ) -> Result<()> {
    76	        if !Arc::ptr_eq(&self.owner, &lease.owner) {
    77	            return Err(Diagnostic {
    78	                kind: ErrorKind::InvalidArgument,
    79	                offset: 0,
    80	            });
    81	        }
    82	        let active = self.active.checked_sub(1).ok_or_else(arithmetic)?;
    83	        job.release(lease.lease)?;
    84	        self.active = active;
    85	        Ok(())
    86	    }
    87	    pub fn tracking_stop(&self, job: &ChargeLedger) -> MemoryStats {
