   104	/// Reserve into a fresh buffer, charge its actual capacity while the old buffer remains
   105	/// live, then transfer values and publish. Before calling, the caller must have an active
   106	/// ledger lease for current Vec capacity; release that old lease after return, when the old
   107	/// allocation is dropped. `None` means the existing charged capacity already suffices.
   108	pub fn reserve_table<T>(
   109	    job: &mut ChargeLedger,
   110	    tag: AllocationTag,
   111	    table: &mut Vec<T>,
   112	    additional: usize,
   113	) -> Result<Option<AllocationLease>> {
   114	    let required = table.len().checked_add(additional).ok_or_else(arithmetic)?;
   115	    required
   116	        .checked_mul(std::mem::size_of::<T>())
   117	        .ok_or_else(arithmetic)?;
   118	    if required <= table.capacity() {
   119	        return Ok(None);
   120	    }
   121	    let mut replacement = Vec::new();
   122	    replacement
   123	        .try_reserve_exact(required)
   124	        .map_err(|_| Diagnostic {
   125	            kind: ErrorKind::OutOfMemory,
   126	            offset: 0,
   127	        })?;
   128	    let actual = replacement
   129	        .capacity()
   130	        .checked_mul(std::mem::size_of::<T>())
   131	        .ok_or_else(arithmetic)?;
   132	    let lease = job.admit(tag, actual)?;
   133	    replacement.append(table);
   134	    std::mem::swap(table, &mut replacement);
   135	    Ok(Some(lease))
   136	}
