 23	static bool view_transform(const svg_shape_document *document,
 24	                           double *scale_x, double *scale_y,
 25	                           double *offset_x, double *offset_y)
 26	{
 27	    if (document == NULL || document->width == 0U || document->height == 0U ||
 28	        !isfinite(document->view_width) || !isfinite(document->view_height) ||
 29	        document->view_width <= 0.0 || document->view_height <= 0.0)
 30	        return false;
 31	    *scale_x = (double)document->width / document->view_width;
 32	    *scale_y = (double)document->height / document->view_height;
 33	    *offset_x = 0.0;
 34	    *offset_y = 0.0;
 35	    svg_shape_aspect aspect = document->preserve_aspect;
 36	    if (!aspect.set) aspect = (svg_shape_aspect){0.5, 0.5, false, false, true};
 37	    if (!aspect.none) {
 38	        double scale = aspect.slice ? fmax(*scale_x, *scale_y) :
 39	                                     fmin(*scale_x, *scale_y);
 40	        *scale_x = scale;
 41	        *scale_y = scale;
 42	        *offset_x = ((double)document->width - document->view_width * scale) *
 43	                    aspect.align_x;
 44	        *offset_y = ((double)document->height - document->view_height * scale) *
 45	                    aspect.align_y;
 46	    }
 47	    return isfinite(*scale_x) && isfinite(*scale_y) &&
 48	           *scale_x > 0.0 && *scale_y > 0.0 &&
 49	           isfinite(*offset_x) && isfinite(*offset_y);
 50	}
