 52	bool svg_shape_bounds_query(const svg_shape_document *document, size_t shape,
 53	                            svg_shape_selection *out)
 54	{
 55	    if (document == NULL || out == NULL || shape >= document->shape_count ||
 56	        document->shape_edge_start == NULL ||
 57	        document->shape_edge_count == NULL || document->shape_sources == NULL ||
 58	        document->edges == NULL) return false;
 59	    size_t first = document->shape_edge_start[shape];
 60	    size_t count = document->shape_edge_count[shape];
 61	    if (first > document->edge_count || count > document->edge_count - first)
 62	        return false;
 63	    double min_x = 0.0, min_y = 0.0, max_x = 0.0, max_y = 0.0;
 64	    if (count != 0U) {
 65	        geom_point point = document->edges[first].a;
 66	        min_x = max_x = point.x;
 67	        min_y = max_y = point.y;
 68	        for (size_t i = first; i < first + count; ++i) {
 69	            const geom_point points[2] = {document->edges[i].a,
 70	                                           document->edges[i].b};
 71	            for (size_t p = 0U; p < 2U; ++p) {
 72	                if (!geom_finite_point(points[p])) return false;
 73	                if (points[p].x < min_x) min_x = points[p].x;
 74	                if (points[p].x > max_x) max_x = points[p].x;
 75	                if (points[p].y < min_y) min_y = points[p].y;
 76	                if (points[p].y > max_y) max_y = points[p].y;
 77	            }
 78	        }
 79	    }
 80	    double sx, sy, ox, oy;
 81	    if (!view_transform(document, &sx, &sy, &ox, &oy)) return false;
 82	    double device_x0 = ox + (min_x - document->view_x) * sx;
 83	    double device_y0 = oy + (min_y - document->view_y) * sy;
 84	    double device_x1 = ox + (max_x - document->view_x) * sx;
 85	    double device_y1 = oy + (max_y - document->view_y) * sy;
 86	    if (!isfinite(device_x0) || !isfinite(device_y0) ||
 87	        !isfinite(device_x1) || !isfinite(device_y1)) return false;
 88	    const svg_shape_source_map *source = &document->shape_sources[shape];
 89	    *out = (svg_shape_selection){
 90	        .shape_index = shape,
 91	        .source_offset = source->offset,
 92	        .source_length = source->length,
 93	        .user_bounds = {min_x, min_y, max_x - min_x, max_y - min_y},
 94	        .device_bounds = {device_x0, device_y0,
 95	                          device_x1 - device_x0, device_y1 - device_y0},
 96	        .transform = source->transform
 97	    };
 98	    return true;
 99	}
