101	static double segment_distance(geom_point point, geom_edge edge)
102	{
103	    double dx = edge.b.x - edge.a.x;
104	    double dy = edge.b.y - edge.a.y;
105	    double length2 = dx * dx + dy * dy;
106	    if (length2 == 0.0) return hypot(point.x - edge.a.x,
107	                                     point.y - edge.a.y);
108	    double t = ((point.x - edge.a.x) * dx + (point.y - edge.a.y) * dy) /
109	               length2;
110	    if (t < 0.0) t = 0.0;
111	    if (t > 1.0) t = 1.0;
112	    return hypot(point.x - (edge.a.x + t * dx),
113	                 point.y - (edge.a.y + t * dy));
114	}
