116	static bool fill_contains(const svg_shape_document *document, size_t shape,
117	                          double x, double y)
118	{
119	    size_t first = document->shape_edge_start[shape];
120	    size_t count = document->shape_edge_count[shape];
121	    int winding = 0;
122	    bool parity = false;
123	    const svg_shape_paint *paint = svg_shape_paint_for_shape(document, shape);
124	    bool visible = paint != NULL && paint->kind == SVG_SHAPE_PAINT_IMAGE;
125	    for (size_t i = first; i < first + count; ++i) {
126	        if (document->colors[i * 4U + 3U] != 0U) visible = true;
127	        geom_edge edge = document->edges[i];
128	        bool upward = edge.a.y <= y && edge.b.y > y;
129	        bool downward = edge.b.y <= y && edge.a.y > y;
130	        if (!upward && !downward) continue;
131	        double crossing = edge.a.x + (y - edge.a.y) *
132	                          (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
133	        if (crossing <= x) continue;
134	        winding += upward ? 1 : -1;
135	        parity = !parity;
136	    }
137	    if (!visible || !document->shape_filled[shape]) return false;
138	    return document->shape_evenodd[shape] ? parity : winding != 0;
139	}
