141	static bool stroke_contains(const svg_shape_document *document, size_t shape,
142	                            geom_point point, double tolerance)
143	{
144	    const svg_shape_stroke *stroke = &document->strokes[shape];
145	    if (stroke->rgba[3] == 0U || stroke->width <= 0.0) return false;
146	    geom_affine inverse = document->shape_stroke_inverse[shape];
147	    geom_point local;
148	    if (!geom_affine_map_point(inverse, point, &local)) return false;
149	    double inverse_norm = sqrt(inverse.a * inverse.a + inverse.b * inverse.b +
150	                               inverse.c * inverse.c + inverse.d * inverse.d);
151	    double radius = stroke->width * 0.5 + tolerance * inverse_norm;
152	    size_t first = document->shape_edge_start[shape];
153	    size_t count = document->shape_edge_count[shape];
154	    if (document->shape_subpath_count != NULL &&
155	        document->shape_subpath_count[shape] != 0U &&
156	        document->path_subpaths != NULL) {
157	        size_t subpath_first = document->shape_subpath_start[shape];
158	        size_t subpath_count = document->shape_subpath_count[shape];
159	        for (size_t i = subpath_first; i < subpath_first + subpath_count; ++i) {
160	            const svg_shape_path_subpath *subpath =
161	                &document->path_subpaths[i];
162	            size_t edges = subpath->edge_count;
163	            if (!subpath->closed && edges != 0U) edges--;
164	            for (size_t e = 0U; e < edges; ++e) {
165	                geom_edge edge = document->edges[subpath->first_edge + e];
166	                if (!geom_affine_map_point(inverse, edge.a, &edge.a) ||
167	                    !geom_affine_map_point(inverse, edge.b, &edge.b)) return false;
168	                if (segment_distance(local, edge) <= radius) return true;
169	            }
170	        }
171	        return false;
172	    }
173	    if (count > 0U && !document->shape_stroke_closed[shape]) count--;
174	    for (size_t i = 0U; i < count; ++i) {
175	        geom_edge edge = document->edges[first + i];
176	        if (!geom_affine_map_point(inverse, edge.a, &edge.a) ||
177	            !geom_affine_map_point(inverse, edge.b, &edge.b)) return false;
178	        if (segment_distance(local, edge) <= radius) return true;
179	    }
180	    return false;
181	}
