183	bool svg_shape_hit_test(const svg_shape_document *document, double x, double y,
184	                        double tolerance, svg_shape_selection *out)
185	{
186	    if (document == NULL || out == NULL || !isfinite(x) || !isfinite(y) ||
187	        !isfinite(tolerance) || tolerance < 0.0 ||
188	        tolerance > 1000000.0 || document->shape_sources == NULL ||
189	        document->shape_edge_start == NULL ||
190	        document->shape_edge_count == NULL || document->shape_filled == NULL ||
191	        document->shape_evenodd == NULL || document->strokes == NULL ||
192	        document->shape_stroke_inverse == NULL) return false;
193	    for (size_t reverse = document->shape_count; reverse != 0U; --reverse) {
194	        size_t shape = reverse - 1U;
195	        bool allowed = svg_clip_contains(document->clips == NULL ? NULL :
196	                                         document->clips[shape], x, y);
197	        if (!allowed) continue;
198	        bool inside = fill_contains(document, shape, x, y);
199	        if (!inside && !stroke_contains(document, shape,
200	                (geom_point){x, y}, tolerance)) continue;
201	        return svg_shape_bounds_query(document, shape, out);
202	    }
203	    return false;
204	}
