206	bool svg_shape_element_at_offset(const svg_shape_document *document,
207	                                 size_t source_offset,
208	                                 svg_shape_selection *out)
209	{
210	    if (document == NULL || out == NULL || document->shape_sources == NULL)
211	        return false;
212	    size_t best = SIZE_MAX;
213	    size_t best_length = SIZE_MAX;
214	    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
215	        const svg_shape_source_map *source = &document->shape_sources[shape];
216	        if (source->length == 0U || source_offset < source->offset ||
217	            source_offset - source->offset >= source->length) continue;
218	        if (source->length < best_length ||
219	            (source->length == best_length && shape > best)) {
220	            best = shape;
221	            best_length = source->length;
222	        }
223	    }
224	    return best != SIZE_MAX && svg_shape_bounds_query(document, best, out);
225	}
