  9	typedef struct svg_alloc_record {
 10	    void *pointer;
 11	    size_t size;
 12	    svg_shape_alloc_tag tag;
 13	    uint8_t state;
 14	} svg_alloc_record;
 15	
 16	static svg_alloc_record records[SVG_ALLOC_TRACKER_CAPACITY];
 17	static svg_shape_alloc_stats current;
 18	static bool active;
 19	
 20	static size_t pointer_hash(void *pointer)
 21	{
 22	    size_t value = (size_t)(uintptr_t)pointer >> 4U;
 23	    value ^= value >> 17U;
 24	    value *= (size_t)0xed5ad4bbU;
 25	    value ^= value >> 11U;
 26	    return value & (SVG_ALLOC_TRACKER_CAPACITY - 1U);
 27	}
 28	
 29	static void add_saturating(size_t *target, size_t amount)
 30	{
 31	    if (amount > SIZE_MAX - *target) {
 32	        *target = SIZE_MAX;
 33	        current.overflow = true;
 34	    } else {
 35	        *target += amount;
 36	    }
 37	}
 38	
 39	static size_t find_record(void *pointer, bool insertion)
 40	{
 41	    if (pointer == NULL) return SVG_ALLOC_TRACKER_CAPACITY;
 42	    size_t slot = pointer_hash(pointer), deleted = SVG_ALLOC_TRACKER_CAPACITY;
 43	    for (size_t probes = 0U; probes < SVG_ALLOC_TRACKER_CAPACITY; ++probes) {
 44	        svg_alloc_record *record = &records[slot];
 45	        if (record->state == 0U)
 46	            return insertion && deleted != SVG_ALLOC_TRACKER_CAPACITY ?
 47	                deleted : slot;
 48	        if (record->state == 2U) {
 49	            if (deleted == SVG_ALLOC_TRACKER_CAPACITY) deleted = slot;
 50	        } else if (record->pointer == pointer) {
 51	            return slot;
 52	        }
 53	        slot = (slot + 1U) & (SVG_ALLOC_TRACKER_CAPACITY - 1U);
 54	    }
 55	    return insertion ? deleted : SVG_ALLOC_TRACKER_CAPACITY;
 56	}
 57	
 58	static void track_add(void *pointer, size_t size)
 59	{
 60	    if (!active || pointer == NULL) return;
 61	    size_t slot = find_record(pointer, true);
 62	    if (slot == SVG_ALLOC_TRACKER_CAPACITY) {
 63	        current.overflow = true;
 64	        return;
 65	    }
 66	    svg_alloc_record *record = &records[slot];
 67	    if (record->state == 1U) {
 68	        if (record->size <= current.live_bytes)
 69	            current.live_bytes -= record->size;
 70	        else
 71	            current.live_bytes = 0U;
 72	    }
 73	    *record = (svg_alloc_record){pointer, size, SVG_SHAPE_ALLOC_TAG_NONE, 1U};
 74	    add_saturating(&current.total_allocated_bytes, size);
 75	    add_saturating(&current.allocation_count, 1U);
 76	    add_saturating(&current.live_bytes, size);
 77	    if (current.live_bytes > current.peak_live_bytes)
 78	        current.peak_live_bytes = current.live_bytes;
 79	}
 80	
 81	static void track_remove(void *pointer)
 82	{
 83	    if (!active || pointer == NULL) return;
 84	    size_t slot = find_record(pointer, false);
 85	    if (slot == SVG_ALLOC_TRACKER_CAPACITY) return;
 86	    svg_alloc_record *record = &records[slot];
 87	    if (record->size <= current.live_bytes)
 88	        current.live_bytes -= record->size;
 89	    else {
 90	        current.live_bytes = 0U;
 91	        current.overflow = true;
 92	    }
 93	    record->pointer = NULL;
 94	    record->size = 0U;
 95	    record->tag = SVG_SHAPE_ALLOC_TAG_NONE;
 96	    record->state = 2U;
 97	}
