129	void *svg_shape_realloc(void *pointer, size_t size)
130	{
131	    if (!active) return realloc(pointer, size);
132	    size_t previous_size = 0U;
133	    size_t previous_slot = find_record(pointer, false);
134	    bool tracked = previous_slot != SVG_ALLOC_TRACKER_CAPACITY;
135	    if (tracked) previous_size = records[previous_slot].size;
136	    void *grown = realloc(pointer, size);
137	    if (grown == NULL) return NULL;
138	    if (tracked) track_remove(pointer);
139	    track_add(grown, size);
140	    (void)previous_size;
141	    return grown;
142	}
