150	bool svg_shape_alloc_set_tag(void *pointer, svg_shape_alloc_tag tag)
151	{
152	    if (!active || pointer == NULL) return false;
153	    size_t slot = find_record(pointer, false);
154	    if (slot == SVG_ALLOC_TRACKER_CAPACITY) return false;
155	    svg_alloc_record *record = &records[slot];
156	    size_t *counter = tag == SVG_SHAPE_ALLOC_TAG_TOKEN_ARRAY ?
157	        &current.token_array_bytes :
158	        tag == SVG_SHAPE_ALLOC_TAG_REFERENCE_INDEX ?
159	        &current.reference_index_bytes :
160	        tag == SVG_SHAPE_ALLOC_TAG_CLIP_COPY ? &current.clip_copy_bytes :
161	        tag == SVG_SHAPE_ALLOC_TAG_OUTPUT ? &current.output_bytes : NULL;
162	    if (counter == NULL) return false;
163	    add_saturating(counter, record->size);
164	    record->tag = tag;
165	    return true;
166	}
