114	static bool decode_reference_memory_bounds_check(void)
115	{
116	    static const char prefix[] =
117	        "<svg width=\"8\" height=\"8\"><defs><linearGradient id=\"paint\"><stop stop-color=\"red\"/><stop offset=\"1\" stop-color=\"blue\"/></linearGradient><clipPath id=\"clip\" clipPathUnits=\"userSpaceOnUse\"><rect width=\"8\" height=\"8\"/></clipPath><g id=\"target\"><rect width=\"8\" height=\"8\" fill=\"url(#paint)\"/></g></defs><!--";
118	    static const char use[] = "<use href=\"#target\"/>";
119	    static const char middle[] = "-->";
120	    static const char suffix[] =
121	        "<rect width=\"8\" height=\"8\" fill=\"url(#paint)\" clip-path=\"url(#clip)\"/></svg>";
122	    const size_t use_count_many = 32U;
123	    const size_t padding_one = 64U * 1024U;
124	    size_t use_length = sizeof(use) - 1U;
125	    if (use_length == 0U || use_count_many - 1U > padding_one / use_length)
126	        return false;
127	    size_t padding_many = padding_one - (use_count_many - 1U) * use_length;
128	    size_t base_length = sizeof(prefix) - 1U + sizeof(middle) - 1U +
129	                         sizeof(suffix) - 1U;
130	    if (base_length > SIZE_MAX - padding_one - use_length) return false;
131	    size_t one_length = base_length + padding_one + use_length;
132	    size_t many_length = base_length + padding_many + use_count_many * use_length;
133	    if (one_length != many_length) return false;
134	    uint8_t *small = NULL, *padded_one = NULL, *padded_many = NULL;
135	    size_t small_length = 0U, one_size = 0U, many_size = 0U;
136	    if (!build_allocation_source(0U, 1U, &small, &small_length) ||
137	        !build_allocation_source(padding_one, 1U, &padded_one, &one_size) ||
138	        !build_allocation_source(padding_many, use_count_many,
139	                                 &padded_many, &many_size)) {
140	        free(small); free(padded_one); free(padded_many);
141	        return false;
142	    }
143	    if (one_size != many_size) {
144	        free(small); free(padded_one); free(padded_many);
145	        return false;
146	    }
147	    svg_shape_alloc_stats stats[3] = {{0}};
148	    size_t index_bytes[3] = {0U}, lookup_probes[3] = {0U};
149	    bool ok = measure_allocation_source(small, small_length, &stats[0],
150	                                        &index_bytes[0], &lookup_probes[0]) &&
151	              measure_allocation_source(padded_one, one_size, &stats[1],
152	                                        &index_bytes[1], &lookup_probes[1]) &&
153	              measure_allocation_source(padded_many, many_size, &stats[2],
154	                                        &index_bytes[2], &lookup_probes[2]);
155	    if (ok) {
156	        for (size_t i = 0U; i < 3U; ++i) {
157	            ok = ok && !stats[i].overflow && stats[i].peak_live_bytes != 0U &&
158	                 stats[i].total_allocated_bytes >= stats[i].peak_live_bytes &&
159	                 stats[i].allocation_count != 0U && stats[i].clip_copy_bytes != 0U &&
160	                 stats[i].output_bytes == 8U * 8U * 4U &&
161	                 stats[i].reference_index_bytes == index_bytes[i] &&
162	                 index_bytes[i] == SVG_REFERENCE_ID_TABLE_CAPACITY * sizeof(uint32_t) &&
163	                 lookup_probes[i] != 0U;
164	        }
165	        size_t small_non_token = stats[0].total_allocated_bytes -
166	            stats[0].token_array_bytes;
167	        size_t padded_non_token = stats[1].total_allocated_bytes -
168	            stats[1].token_array_bytes;
169	        /* Tokens now come from the streaming tokenizer, so their storage tracks
170	         * the real token count instead of a source-length pre-allocation
171	         * (source.len / 2 tokens needed about 4.7 GiB for a 94 MiB document).
172	         * The invariants this check exists for are unchanged: token memory must
173	         * not grow with <use> expansion, and non-token memory must not grow with
174	         * comment padding. */
175	        size_t token_growth = stats[2].token_array_bytes > stats[1].token_array_bytes ?
176	            stats[2].token_array_bytes - stats[1].token_array_bytes : 0U;
177	        size_t use_growth_budget = (use_count_many - 1U) * 2048U;
178	        ok = ok && stats[0].token_array_bytes > 0U &&
179	             stats[1].token_array_bytes > 0U && stats[2].token_array_bytes > 0U &&
180	             stats[1].token_array_bytes <= one_size &&
