  1	//! Faithful safe construction equivalent for the assigned frozen C fixture.
  2	fn build_allocation_source(padding: usize, uses: usize) -> Option<Vec<u8>> {
  3	    const PREFIX:&[u8]=b"<svg width=\"8\" height=\"8\"><defs><linearGradient id=\"paint\"><stop stop-color=\"red\"/><stop offset=\"1\" stop-color=\"blue\"/></linearGradient><clipPath id=\"clip\" clipPathUnits=\"userSpaceOnUse\"><rect width=\"8\" height=\"8\"/></clipPath><g id=\"target\"><rect width=\"8\" height=\"8\" fill=\"url(#paint)\"/></g></defs><!--";
  4	    const MIDDLE: &[u8] = b"-->";
  5	    const USE: &[u8] = b"<use href=\"#target\"/>";
  6	    const SUFFIX: &[u8] =
  7	        b"<rect width=\"8\" height=\"8\" fill=\"url(#paint)\" clip-path=\"url(#clip)\"/></svg>";
  8	    if uses == 0 {
  9	        return None;
 10	    }
 11	    let len = PREFIX
 12	        .len()
 13	        .checked_add(padding)?
 14	        .checked_add(MIDDLE.len())?
 15	        .checked_add(uses.checked_mul(USE.len())?)?
 16	        .checked_add(SUFFIX.len())?;
 17	    let mut out = Vec::new();
 18	    out.try_reserve_exact(len).ok()?;
 19	    out.extend_from_slice(PREFIX);
 20	    out.resize(out.len().checked_add(padding)?, b'p');
 21	    out.extend_from_slice(MIDDLE);
 22	    for _ in 0..uses {
 23	        out.extend_from_slice(USE);
 24	    }
 25	    out.extend_from_slice(SUFFIX);
 26	    (out.len() == len).then_some(out)
 27	}
