 33	    let many = build_allocation_source(65536 - 31 * 21, 32).unwrap();
 34	    assert_eq!(padded.len(), many.len());
 35	    assert!(small.starts_with(b"<svg width=\"8\" height=\"8\">"));
 36	    assert!(small.ends_with(b"clip-path=\"url(#clip)\"/></svg>"));
 37	    assert!(padded.windows(8).any(|w| w == b"pppppppp"));
