   117	    fn publish_shape(
   118	        &mut self,
   119	        i: usize,
   120	        id: ShapeId,
   121	        input: ShapeInput,
   122	        control: &mut dyn WorkControl,
   123	    ) -> Result<()> {
   124	        let scene = &mut self.scenes[i];
