   126	        let number_first = scene.path_numbers.len();
   127	        let mut shape = input.shape;
   128	        shape.edges = TableRange {
   129	            first: edge_first,
   130	            count: input.path.edges.len(),
   131	        };
   132	        shape.subpaths = TableRange {
   133	            first: scene.path_subpaths.len(),
   134	            count: input.path.subpaths.len(),
   135	        };
   136	        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
   137	            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
   138	            scene.edges.push(edge);
   139	            scene.edge_colors.push(color);
   140	            scene.edge_shape_ids.push(id.slot);
   141	        }
   142	        for mut subpath in input.path.subpaths {
   143	            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
   144	            subpath.first_edge = add(subpath.first_edge, edge_first)?;
   145	            scene.path_subpaths.push(subpath);
   146	        }
   147	        for mut path in input.path.segments {
   148	            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
   149	            path.first_edge = add(path.first_edge, edge_first)?;
   150	            path.first_number = add(path.first_number, number_first)?;
   151	            scene
   152	                .path_segments
   153	                .push(ScenePathSegment { path, shape: id });
   154	        }
   155	        for number in input.path.numbers {
   156	            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
   157	            scene.path_numbers.push(number);
   158	        }
   159	        control.checkpoint().map_err(stopped)?;
   160	        scene.shapes.push(shape);
   161	        scene.shapes_serials.push(id.serial);
   162	        Ok(())
   163	    }
