 91	impl ChargeLedger {
 92	    pub fn new(source: &SourceOwner, reserved_bytes: usize, max_leases: usize) -> Result<Self> {
 93	        if source.len() > 1 << 30 {
 94	            return Err(limit(LimitKind::SourceBytes));
 95	        }
 96	        if source.capacity() > reserved_bytes {
 97	            return Err(limit(LimitKind::ReservedBytes));
 98	        }
 99	        let owner = NEXT_LEDGER
100	            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
101	            .map_err(|_| arithmetic())?;
102	        let source_bytes = source.capacity();
103	        Ok(Self {
104	            source: source.clone(),
105	            owner,
106	            next: 1,
107	            max_leases,
108	            reserved_bytes,
109	            per_tag: [0; 5],
110	            entries: Vec::new(),
111	            free: None,
112	            stats: RenderMemoryStats {
113	                live_bytes: source_bytes,
114	                peak_live_bytes: source_bytes,
115	                source_bytes,
116	                ..Default::default()
117	            },
118	            work: Default::default(),
119	        })
120	    }
121	    pub fn source_owner(&self) -> &SourceOwner {
122	        &self.source
123	    }
124	    pub fn available(&self) -> usize {
125	        self.reserved_bytes - self.stats.live_bytes
126	    }
127	    pub fn stats(&self) -> RenderMemoryStats {
128	        let mut s = self.stats;
129	        s.token_array_bytes = self.per_tag[1];
130	        s.reference_index_bytes = self.per_tag[2];
131	        s.clip_copy_bytes = self.per_tag[3];
132	        s.output_bytes = self.per_tag[4];
133	        s
134	    }
135	    /// Capacity supplied by an actual Vec, not logical element count.
136	    pub fn admit_vec<T>(&mut self, tag: AllocationTag, values: &Vec<T>) -> Result<AllocationLease> {
137	        self.admit(tag, bytes(values)?)
138	    }
139	    /// Aggregate nested capacity computed by the full owning module (e.g. scratch).
140	    /// Callers retain the buffer and release its lease at the same lifetime boundary.
141	    pub fn admit(&mut self, tag: AllocationTag, amount: usize) -> Result<AllocationLease> {
142	        match self.admit_inner(tag, amount) {
143	            Err(error) if error.kind == ErrorKind::Limit(LimitKind::Arithmetic) => {
144	                self.stats.overflow = true;
145	                Err(error)
146	            }
147	            result => result,
148	        }
149	    }
150	    fn admit_inner(&mut self, tag: AllocationTag, amount: usize) -> Result<AllocationLease> {
151	        let next = self.next.checked_add(1).ok_or_else(arithmetic)?;
152	        let count = self
153	            .stats
154	            .allocation_count
155	            .checked_add(usize::from(amount != 0))
156	            .ok_or_else(arithmetic)?;
157	        let tagged = add(self.per_tag[tag as usize], amount)?;
158	        let history = add(self.stats.total_allocated_bytes, amount)?;
159	        let total = add(self.stats.live_bytes, amount)?;
160	        let overlap = self
161	            .reserved_bytes
162	            .checked_sub(total)
163	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
164	        if self.free.is_none() {
165	            count.checked_add(1).ok_or_else(arithmetic)?;
166	            let (new, old) = reserve(
167	                &mut self.entries,
168	                1,
169	                self.max_leases,
170	                overlap.min(usize::MAX - history),
171	            )?;
172	            if new != 0 {
173	                let current = add(total, new)?;
174	                let new_history = add(history, new)?;
175	                let new_count = count.checked_add(1).ok_or_else(arithmetic)?;
176	                self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(current);
177	                self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
178	                self.per_tag[0] = add(self.per_tag[0] - old, new)?;
179	                self.stats.total_allocated_bytes = new_history - amount;
180	                self.stats.allocation_count = new_count - usize::from(amount != 0);
181	            }
182	        }
183	        // Recalculate after registry growth. Metadata is itself retained and charged.
184	        let current = add(self.stats.live_bytes, amount)?;
185	        if current > self.reserved_bytes {
186	            return Err(limit(LimitKind::ReservedBytes));
187	        }
188	        let serial = self.next;
189	        self.next = next;
190	        let slot = if let Some(slot) = self.free {
191	            self.free = self.entries[slot].next_free;
192	            slot
193	        } else {
194	            self.entries.len()
195	        };
196	        let entry = Entry {
197	            serial,
198	            tag,
199	            bytes: amount,
200	            active: true,
201	            next_free: None,
202	        };
203	        if slot == self.entries.len() {
204	            self.entries.push(entry);
205	        } else {
206	            self.entries[slot] = entry;
207	        }
208	        self.per_tag[tag as usize] = if tag == AllocationTag::None {
209	            add(self.per_tag[0], amount)?
210	        } else {
211	            tagged
212	        };
213	        self.stats.live_bytes = current;
214	        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(current);
215	        self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, amount)?;
216	        self.stats.allocation_count = self
217	            .stats
218	            .allocation_count
219	            .checked_add(usize::from(amount != 0))
220	            .ok_or_else(arithmetic)?;
221	        Ok(AllocationLease {
222	            owner: self.owner,
223	            slot,
224	            serial,
225	        })
226	    }
227	    pub fn release(&mut self, lease: AllocationLease) -> Result<()> {
228	        if lease.owner != self.owner {
229	            return Err(invalid(0));
230	        }
231	        let entry = self.entries.get_mut(lease.slot).ok_or_else(|| invalid(0))?;
232	        if !entry.active || entry.serial != lease.serial {
233	            return Err(invalid(0));
234	        }
235	        entry.active = false;
236	        self.per_tag[entry.tag as usize] -= entry.bytes;
237	        self.stats.live_bytes -= entry.bytes;
238	        entry.next_free = self.free;
239	        self.free = Some(lease.slot);
240	        Ok(())
241	    }
242	}
285	            })
286	        }
