 47	static bool build_allocation_source(size_t padding, size_t uses,
 48	                                    uint8_t **out, size_t *out_length)
 49	{
 50	    static const char prefix[] =
 51	        "<svg width=\"8\" height=\"8\"><defs><linearGradient id=\"paint\"><stop stop-color=\"red\"/><stop offset=\"1\" stop-color=\"blue\"/></linearGradient><clipPath id=\"clip\" clipPathUnits=\"userSpaceOnUse\"><rect width=\"8\" height=\"8\"/></clipPath><g id=\"target\"><rect width=\"8\" height=\"8\" fill=\"url(#paint)\"/></g></defs><!--";
 52	    static const char middle[] = "-->";
 53	    static const char use[] = "<use href=\"#target\"/>";
 54	    static const char suffix[] =
 55	        "<rect width=\"8\" height=\"8\" fill=\"url(#paint)\" clip-path=\"url(#clip)\"/></svg>";
 56	    if (out == NULL || out_length == NULL || uses == 0U) return false;
 57	    size_t length = sizeof(prefix) - 1U;
 58	    if (padding > SIZE_MAX - length) return false;
 59	    length += padding;
 60	    if (sizeof(middle) - 1U > SIZE_MAX - length) return false;
 61	    length += sizeof(middle) - 1U;
 62	    if (uses > (SIZE_MAX - length) / (sizeof(use) - 1U)) return false;
 63	    length += uses * (sizeof(use) - 1U);
 64	    if (sizeof(suffix) - 1U > SIZE_MAX - length) return false;
 65	    length += sizeof(suffix) - 1U;
 66	    uint8_t *source = malloc(length);
 67	    if (source == NULL) return false;
 68	    size_t cursor = 0U;
 69	    memcpy(source + cursor, prefix, sizeof(prefix) - 1U);
 70	    cursor += sizeof(prefix) - 1U;
 71	    memset(source + cursor, 'p', padding);
 72	    cursor += padding;
 73	    memcpy(source + cursor, middle, sizeof(middle) - 1U);
 74	    cursor += sizeof(middle) - 1U;
 75	    for (size_t i = 0U; i < uses; ++i) {
 76	        memcpy(source + cursor, use, sizeof(use) - 1U);
 77	        cursor += sizeof(use) - 1U;
 78	    }
 79	    memcpy(source + cursor, suffix, sizeof(suffix) - 1U);
 80	    cursor += sizeof(suffix) - 1U;
 81	    *out = source;
 82	    *out_length = cursor;
 83	    return cursor == length;
 84	}
