 86	static bool measure_allocation_source(const uint8_t *source, size_t length,
 87	                                     svg_shape_alloc_stats *stats,
 88	                                     size_t *index_bytes, size_t *lookup_probes)
 89	{
 90	    if (source == NULL || stats == NULL || index_bytes == NULL ||
 91	        lookup_probes == NULL || length > UINT32_MAX) return false;
 92	    unsigned char before[CC_SHA256_DIGEST_LENGTH], after[CC_SHA256_DIGEST_LENGTH];
 93	    if (CC_SHA256(source, (CC_LONG)length, before) == NULL) return false;
 94	    svg_shape_document document = {0};
 95	    svg_shape_diagnostic diagnostic = {0};
 96	    svg_shape_decode_memory_bounds bounds = {0};
 97	    raster_tile tile = {0};
 98	    svg_shape_alloc_tracking_start();
 99	    svg_shape_error error = svg_shape_decode_source_with_bounds(
100	        (base_bytes){source, length}, &document, &diagnostic, &bounds);
101	    bool ok = error == SVG_SHAPE_ERROR_NONE &&
102	              raster_shape_render(&document, &tile, &diagnostic);
103	    svg_shape_alloc_tracking_stop(stats);
104	    *index_bytes = bounds.reference_index_bytes;
105	    *lookup_probes = bounds.reference_lookup_probes;
106	    if (ok) ok = document.source.ptr == source && document.source.len == length &&
107	        CC_SHA256(source, (CC_LONG)length, after) != NULL &&
108	        memcmp(before, after, sizeof(before)) == 0;
109	    raster_tile_destroy(&tile);
110	    svg_shape_document_destroy(&document);
111	    return ok;
112	}
