   565	fn source_assignment_is_checked_and_happens_before_append() {
   566	    let source = b"<path d='M0 0 L1 0'/>";
   567	    let span = Span {
   568	        start: 0,
   569	        end: source.len(),
   570	    };
   571	    let shape = Shape::new(SourceMap {
   572	        element: Span { start: 0, end: 0 },
   573	        transform: affine_identity(),
   574	        transform_node: None,
   575	    });
   576	    let d = b"M0 0 L1 0";
   577	    let start = source.windows(d.len()).position(|w| w == d).unwrap();
   578	    let path = vexel_svg_path::parse_path(
   579	        source,
   580	        Span {
   581	            start,
   582	            end: start + d.len(),
   583	        },
   584	        affine_identity(),
   585	        Default::default(),
   586	    )
   587	    .unwrap();
   588	    let colors = vec![[1, 2, 3, 255]; path.edges.len()];
   589	    let mut input = ShapeInput {
   590	        shape: shape.clone(),
   591	        path,
   592	        edge_colors: colors,
   593	    };
   594	    source_assign(&mut input, source, span).unwrap();
   595	    assert_eq!(input.shape.source.element, span);
   596	    assert!(
   597	        source_assign(
   598	            &mut input,
   599	            source,
   600	            Span {
   601	                start: usize::MAX,
   602	                end: usize::MAX
   603	            }
   604	        )
   605	        .is_err()
   606	    );
   607	    let owner = Arc::new(source.to_vec());
   608	    let animation = vexel_svg_animation::parse_owned(&owner, &[]).unwrap();
   609	    let viewport = Viewport {
   610	        width: 10,
   611	        height: 10,
   612	        view_x: 0.,
   613	        view_y: 0.,
   614	        view_width: 10.,
   615	        view_height: 10.,
   616	        aspect: Default::default(),
   617	    };
   618	    let mut builder = SceneBuilder::new(owner, animation, 1, viewport, Limits::default()).unwrap();
   619	    let root = builder.root_id();
   620	    let id = builder.append_shape(root, input, &mut Run).unwrap();
   621	    let graph = builder.freeze().unwrap();
   622	    assert_eq!(graph.root().shape(id).unwrap().source.element, span);
   623	}
