    11	fn explicit_capacity_is_charged_and_released() {
    12	    let mut job = ledger();
    13	    let mut tracking = AllocationTracking::tracking_start(&job);
    14	    let baseline = job.stats().live_bytes;
    15	    let mut values = Vec::<u32>::new();
    16	    values.try_reserve_exact(8).unwrap();
    17	    let lease = tracking
    18	        .track_capacity(&mut job, AllocationTag::TokenArray, &values)
    19	        .unwrap();
    20	    let stats = tracking.tracking_stop(&job);
    21	    assert!(stats.token_array_bytes >= 8 * std::mem::size_of::<u32>());
    22	    assert!(stats.live_bytes >= stats.token_array_bytes + stats.source_bytes);
    23	    assert!(stats.source_bytes > 0);
    24	    let before_release = job.stats().live_bytes;
    25	    tracking.release(&mut job, &lease).unwrap();
    26	    assert_eq!(
    27	        job.stats().live_bytes,
    28	        before_release - stats.token_array_bytes
    29	    );
    30	    assert!(job.stats().live_bytes > baseline); // retained lease registry capacity is charged
    31	}
