    33	#[test]
    34	fn tracking_scope_enforces_record_cap_and_rejects_foreign_release() {
    35	    let source = Arc::new(Vec::new());
    36	    let mut job = ChargeLedger::new(&source, 16 * 1024 * 1024, SVG_ALLOC_TRACKER_CAPACITY).unwrap();
    37	    let mut owner = AllocationTracking::tracking_start(&job);
    38	    let mut foreign = AllocationTracking::tracking_start(&job);
    39	    let values = Vec::<()>::with_capacity(1);
    40	    let first = owner
    41	        .track_capacity(&mut job, AllocationTag::None, &values)
    42	        .unwrap();
    43	    assert_eq!(
    44	        foreign.release(&mut job, &first).unwrap_err().kind,
    45	        vexel_scene::ErrorKind::InvalidArgument
    46	    );
    47	    owner.release(&mut job, &first).unwrap();
    48	    let mut leases = Vec::new();
    49	    leases
    50	        .try_reserve_exact(SVG_ALLOC_TRACKER_CAPACITY)
    51	        .unwrap();
    52	    for _ in 0..SVG_ALLOC_TRACKER_CAPACITY {
    53	        leases.push(
    54	            owner
    55	                .track_capacity(&mut job, AllocationTag::None, &values)
    56	                .unwrap(),
    57	        );
    58	    }
    59	    let error = owner
    60	        .track_capacity(&mut job, AllocationTag::None, &values)
    61	        .unwrap_err();
    62	    assert_eq!(
    63	        error.kind,
    64	        vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Nodes)
    65	    );
    66	    for lease in &leases {
    67	        owner.release(&mut job, lease).unwrap();
    68	    }
    69	}
