    71	#[test]
    72	fn reserve_table_charges_replacement_before_publishing() {
    73	    let mut job = ledger();
    74	    let mut values = vec![3u32, 5];
    75	    let old_bytes = values.capacity() * std::mem::size_of::<u32>();
    76	    let old_lease = job.admit_vec(AllocationTag::Output, &values).unwrap();
    77	    let lease = reserve_table(&mut job, AllocationTag::Output, &mut values, 64)
    78	        .unwrap()
    79	        .unwrap();
    80	    assert_eq!(&values[..2], &[3, 5]);
    81	    assert!(values.capacity() >= 66);
    82	    let new_bytes = values.capacity() * std::mem::size_of::<u32>();
    83	    assert_eq!(job.stats().output_bytes, old_bytes + new_bytes);
    84	    job.release(old_lease).unwrap();
    85	    assert_eq!(job.stats().output_bytes, new_bytes);
    86	    job.release(lease).unwrap();
    87	    assert_eq!(job.stats().output_bytes, 0);
    88	}
